import{_ as c,C as i,o as l,c as h,aj as r,E as o,j as e,a}from"./chunks/framework.DkvuVDKz.js";const v=JSON.parse('{"title":"Card 卡片","description":"","frontmatter":{},"headers":[],"relativePath":"components/card.md","filePath":"components/card.md","lastUpdated":1789272501000}'),n={name:"components/card.md"};function s(b,d,u,p,x,f){const t=i("XhDemo");return l(),h("div",null,[d[0]||(d[0]=r('<h1 id="card-卡片" tabindex="-1">Card 卡片 <a class="header-anchor" href="#card-卡片" aria-label="Permalink to &quot;Card 卡片&quot;">​</a></h1><p>一块有边界的内容容器：封面、标题、正文与页脚各占一段。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/card" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/card.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/card" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/card" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/card.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>除了 root，封面、头、身、脚都可选；只写用得上的那几段</p>',5)),o(t,{src:"card/01-basic"}),d[1]||(d[1]=r('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;card&quot;</code>：<strong><code>root</code></strong> · <code>media</code> · <code>header</code> · <code>title</code> · <code>description</code> · <code>body</code> · <code>footer</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="变体" tabindex="-1">变体 <a class="header-anchor" href="#变体" aria-label="Permalink to &quot;变体&quot;">​</a></h3><p>variant 只改描边、底色与投影怎么用，各段的排版三档一致</p>',6)),o(t,{src:"card/02-variant"}),d[2]||(d[2]=e("h3",{id:"尺寸",tabindex:"-1"},[a("尺寸 "),e("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),d[3]||(d[3]=e("p",null,"size 换的是各段的内边距与标题字号，不写 size 即默认档",-1)),o(t,{src:"card/03-size"}),d[4]||(d[4]=e("h3",{id:"分段与悬停",tabindex:"-1"},[a("分段与悬停 "),e("a",{class:"header-anchor",href:"#分段与悬停","aria-label":'Permalink to "分段与悬停"'},"​")],-1)),d[5]||(d[5]=e("p",null,"split 在段与段之间画一条分隔线；hoverable 只在能用指针的设备上抬起",-1)),o(t,{src:"card/04-split"}),d[6]||(d[6]=e("h3",{id:"带封面",tabindex:"-1"},[a("带封面 "),e("a",{class:"header-anchor",href:"#带封面","aria-label":'Permalink to "带封面"'},"​")],-1)),d[7]||(d[7]=e("p",null,"封面顶到根的边上、不吃内边距，圆角由根统一裁",-1)),o(t,{src:"card/05-cover"}),d[8]||(d[8]=r('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>把一组相关信息收成一个可以整体感知的单元。</li><li>内容块之间需要视觉边界。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>页面上每一块都套卡片：边界失效，只剩噪音。</li><li>只是要一条分隔：用<a href="./separator">分隔线</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>七个部件全部可选，只写用得上的那几段。</li><li><code>split</code> 在各段之间画线，<code>hoverable</code> 给出悬停反馈。</li></ul><p>默认形态使用纯净实体面、透明边界和轻接触影；<code>outline</code> 提供显式描边，<code>subtle</code> 使用淡色底，<code>elevated</code> 提升投影层级，<code>ghost</code> 保持透明。<code>hoverable</code> 会按形态增强边界、底色或投影，不移动布局。高对比模式为有实体边界的形态补足系统描边，打印时移除投影。</p><p>标题与正文统一到 14px 基准排版，描述降为 13px 次级字号；相邻的头、身、脚只产生一份 8 / 12 / 16px 纵向间距，单独使用任一部件时仍保留完整内边距。这个间距模型保留可选部件与 <code>split</code> 结构，不把全部内容压进单一 <code>gap + padding</code> 容器。</p><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>里面放<a href="./descriptions">描述列表</a>、<a href="./table">表格</a>、<a href="./statistic">统计数值</a>；页脚放<a href="./button-group">按钮组</a>。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>整卡可点时要有明显的悬停与聚焦反馈，并让整卡进 Tab 序列。</li><li>卡片内的留白统一，别让每张卡的内边距不一样。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>卡片套卡片：两层边界互相削弱。</li><li>整卡可点的同时卡内还有别的按钮：点哪里会发生什么不可预期。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-card&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhCardBody</code> <code>XhCardDescription</code> <code>XhCardFooter</code> <code>XhCardHeader</code> <code>XhCardMedia</code> <code>XhCardRoot</code> <code>XhCardTitle</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/card.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>hoverable</code></td><td><code>boolean</code></td><td></td><td>指针悬停时抬起：只落 data-hoverable，抬多少由皮肤定。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，决定各段的内边距与标题字号。</td></tr><tr><td><code>split</code></td><td><code>boolean</code></td><td></td><td>分段：在头、身、脚之间画分隔线。</td></tr><tr><td><code>variant</code></td><td><code>CardVariant</code></td><td></td><td>形态：outline / subtle / elevated / ghost，决定描边、底色与投影怎么用。</td></tr></tbody></table><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getMediaProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getHeaderProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTitleProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getDescriptionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getBodyProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getFooterProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/card.css</code> 使用 <code>[data-scope=&quot;card&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；缺省来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>缺省来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-card-bg</code></td><td><code>root</code></td><td><code>background</code><br><code>background-color</code></td><td><code>default</code><br><code>variant=elevated</code><br><code>variant=subtle</code></td><td><code>--xh-bg-subtle</code><br><code>--xh-bg-surface</code><br><code>--xh-bg-surface-raised</code></td><td>card 的 root 部件 background、background-color 覆盖槽。</td></tr><tr><td><code>--xh-card-bg-hover</code></td><td><code>root</code></td><td><code>background-color</code></td><td><code>@media (hover: hover)</code><br><code>hover</code><br><code>hoverable</code><br><code>variant=elevated</code><br><code>variant=ghost</code><br><code>variant=subtle</code></td><td><code>--xh-bg-subtle</code><br><code>--xh-bg-subtle-hover</code><br><code>--xh-bg-surface</code><br><code>--xh-bg-surface-raised</code></td><td>card 的 root 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-card-body-font-size</code></td><td><code>root</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-text-body-size</code></td><td>card 的 root 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-card-body-line-height</code></td><td><code>root</code></td><td><code>line-height</code></td><td><code>default</code></td><td><code>--xh-text-body-leading</code></td><td>card 的 root 部件 line-height 覆盖槽。</td></tr><tr><td><code>--xh-card-body-pb</code></td><td><code>body</code></td><td><code>padding-block-end</code></td><td><code>not(:last-child)</code></td><td><code>--xh-space-0</code></td><td>card 的 body 部件 padding-block-end 覆盖槽。</td></tr><tr><td><code>--xh-card-body-pt</code></td><td><code>body</code><br><code>header</code></td><td><code>padding-block-start</code></td><td><code>default</code></td><td><code>--xh-_card-section-gap</code></td><td>card 的 body、header 部件 padding-block-start 覆盖槽。</td></tr><tr><td><code>--xh-card-border</code></td><td><code>root</code></td><td><code>border</code><br><code>border-color</code></td><td><code>default</code><br><code>variant=elevated</code><br><code>variant=ghost</code><br><code>variant=outline</code><br><code>variant=subtle</code></td><td><code>--xh-border-default</code><br><code>transparent</code></td><td>card 的 root 部件 border、border-color 覆盖槽。</td></tr><tr><td><code>--xh-card-border-hover</code></td><td><code>root</code></td><td><code>border-color</code></td><td><code>@media (hover: hover)</code><br><code>hover</code><br><code>hoverable</code><br><code>variant=ghost</code><br><code>variant=outline</code><br><code>variant=subtle</code></td><td><code>--xh-border-default</code><br><code>--xh-border-strong</code><br><code>transparent</code></td><td>card 的 root 部件 border-color 覆盖槽。</td></tr><tr><td><code>--xh-card-description-fg</code></td><td><code>description</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-material-soft-fg-muted</code></td><td>card 的 description 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-card-description-font-size</code></td><td><code>description</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-text-secondary-size</code></td><td>card 的 description 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-card-divider</code></td><td><code>body</code><br><code>footer</code><br><code>root</code></td><td><code>border-block-start</code></td><td><code>split</code></td><td><code>--xh-border-subtle</code></td><td>card 的 body、footer、root 部件 border-block-start 覆盖槽。</td></tr><tr><td><code>--xh-card-fg</code></td><td><code>root</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>card 的 root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-card-footer-gap</code></td><td><code>footer</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-2</code></td><td>card 的 footer 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-card-footer-pt</code></td><td><code>body</code><br><code>footer</code><br><code>header</code></td><td><code>padding-block-start</code></td><td><code>default</code></td><td><code>--xh-_card-section-gap</code></td><td>card 的 body、footer、header 部件 padding-block-start 覆盖槽。</td></tr><tr><td><code>--xh-card-header-gap</code></td><td><code>header</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-1</code></td><td>card 的 header 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-card-header-pb</code></td><td><code>header</code></td><td><code>padding-block-end</code></td><td><code>not(:last-child)</code></td><td><code>--xh-space-0</code></td><td>card 的 header 部件 padding-block-end 覆盖槽。</td></tr><tr><td><code>--xh-card-radius</code></td><td><code>root</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-surface</code></td><td>card 的 root 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-card-shadow</code></td><td><code>root</code></td><td><code>box-shadow</code></td><td><code>default</code><br><code>variant=elevated</code><br><code>variant=ghost</code><br><code>variant=outline</code><br><code>variant=subtle</code></td><td><code>--xh-elevation-lifted</code><br><code>--xh-elevation-raised</code><br><code>none</code></td><td>card 的 root 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-card-shadow-hover</code></td><td><code>root</code></td><td><code>box-shadow</code></td><td><code>@media (hover: hover)</code><br><code>hover</code><br><code>hoverable</code><br><code>variant=elevated</code><br><code>variant=ghost</code><br><code>variant=subtle</code></td><td><code>--xh-elevation-lifted</code><br><code>none</code></td><td>card 的 root 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-card-title-font-size</code></td><td><code>root</code><br><code>title</code></td><td><code>font-size</code></td><td><code>default</code><br><code>size=lg</code></td><td><code>--xh-control-font-lg</code><br><code>--xh-text-label-size</code></td><td>card 的 root、title 部件 font-size 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p><code>background-color</code> · <code>border-color</code> · <code>box-shadow</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h3 id="响应式" tabindex="-1">响应式 <a class="header-anchor" href="#响应式" aria-label="Permalink to &quot;响应式&quot;">​</a></h3><p>皮肤另按输入能力分档：<code>hover: hover</code>——同一份皮肤在触屏与带指针的设备上不一样，与视口宽度无关。</p>',39))])}const m=c(n,[["render",s]]);export{v as __pageData,m as default};
